// Before: the high-level policy depends on low-level IO
class EncryptDirect {
    static void encrypt() throws java.io.IOException {
        int c;
        while ((c = System.in.read()) >= 0) System.out.write(translate(c));
        System.out.flush();
    }
    static int translate(int c) { return Character.isLetter(c) ? c + 1 : c; }
}

// After: dependencies point inward, to the Encrypt policy
interface CharReader { int read() throws java.io.IOException; }
interface CharWriter { void write(int c); }
class Encrypt {
    private final CharReader in; private final CharWriter out;
    Encrypt(CharReader in, CharWriter out) { this.in = in; this.out = out; }
    void run() throws java.io.IOException {
        int c;
        while ((c = in.read()) >= 0) out.write(Character.isLetter(c) ? c + 1 : c);
    }
}
class ConsoleReader implements CharReader {
    public int read() throws java.io.IOException { return System.in.read(); }
}
class ConsoleWriter implements CharWriter {
    public void write(int c) { System.out.write(c); }
}

